44	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
45	import org.springframework.samples.petclinic.rest.dto.VisitDto;
46	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
47	import org.springframework.samples.petclinic.service.ClinicService;
48	import org.springframework.samples.petclinic.util.Households;
49	import org.springframework.samples.petclinic.util.Localities;
50	import org.springframework.security.access.prepost.PreAuthorize;
51	import org.springframework.web.bind.annotation.CrossOrigin;
52	import org.springframework.web.bind.annotation.RequestMapping;
53	import org.springframework.web.bind.annotation.RestController;
54	import org.springframework.web.context.request.RequestAttributes;
55	import org.springframework.web.context.request.RequestContextHolder;
56	import org.springframework.web.context.request.ServletRequestAttributes;
57	import org.springframework.web.util.UriComponentsBuilder;
58	
59	import jakarta.transaction.Transactional;
60	
61	/**
62	 * @author Vitaliy Fedoriv
63	 */
64	
65	@RestController
66	@CrossOrigin(exposedHeaders = "errors, content-type")
67	@RequestMapping("/api")
68	public class OwnerRestControllerV1 implements OwnersApi {
69	
70	    /**
71	     * Dedicated audit logger. On a successful owner create an audit line is emitted here carrying the
72	     * new owner's id, its assigned {@code customerCode}, its {@code registrationDate} and its
73	     * numeric {@code membershipLevel}.
74	     */
75	    private static final org.slf4j.Logger AUDIT = org.slf4j.LoggerFactory.getLogger("AUDIT");
76	
77	    /**
78	     * Name of the optional request header carrying an idempotency token for owner creation.
79	     */
80	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
81	
82	    /**
83	     * Idempotency store mapping a previously seen {@code Idempotency-Key} to the id of the owner
84	     * originally created under it. When a create repeats with a key already present here, the
85	     * originally created owner is returned (200 OK) instead of creating a duplicate.
86	     */
87	    private final java.util.Map<String, Integer> idempotencyKeyToOwnerId =
88	        new java.util.concurrent.ConcurrentHashMap<>();
89	
90	    private final ClinicService clinicService;
91	
92	    private final OwnerMapper ownerMapper;
93	
94	    private final PetMapper petMapper;
95	
96	    private final VisitMapper visitMapper;
97	
98	    public OwnerRestControllerV1(ClinicService clinicService,
99	                                 OwnerMapper ownerMapper,
100	                                 PetMapper petMapper,
101	                                 VisitMapper visitMapper) {
102	        this.clinicService = clinicService;
103	        this.ownerMapper = ownerMapper;
104	        this.petMapper = petMapper;
105	        this.visitMapper = visitMapper;
106	    }
107	
108	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
109	    @Override
110	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
111	        Collection<Owner> owners;
112	        if (lastName != null) {
113	            owners = this.clinicService.findOwnerByLastName(lastName);
114	        } else {
115	            owners = this.clinicService.findAllOwners();
116	        }
117	        if (owners.isEmpty()) {
118	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
119	        }
120	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
121	    }
122	
123	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
124	    @Override
125	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
126	        Owner owner = this.clinicService.findOwnerById(ownerId);
127	        if (owner == null) {
128	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
129	        }
130	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
131	    }
132	
133	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
134	    @Override
135	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
136	        String idempotencyKey = currentIdempotencyKey();
137	        if (idempotencyKey != null) {
138	            Integer existingId = idempotencyKeyToOwnerId.get(idempotencyKey);
139	            if (existingId != null) {
140	                Owner existing = this.clinicService.findOwnerById(existingId);
141	                if (existing != null) {
142	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
143	                }
144	            }
145	        }
146	        HttpHeaders headers = new HttpHeaders();
147	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
148	        applyAddress(owner, ownerFieldsDto);
149	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
150	        rejectFutureRegistrationDate(registrationDate);
151	        if (registrationDate == null) {
152	            registrationDate = java.time.LocalDate.now();
153	        }
154	        registrationDate = toBusinessDay(registrationDate);
155	        owner.setRegistrationDate(registrationDate);
156	        rejectDailyLimitReached(registrationDate);
157	        rejectCityAtCapacity(owner.getCity());
158	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
159	        owner.setTelephone(telephone);
160	        String email = normalizeEmail(ownerFieldsDto.getEmail());
161	        owner.setEmail(email);
162	        owner.setPostcode(validatePostcode(owner.getCity(), ownerFieldsDto.getPostcode()));
163	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
164	        rejectDuplicateIdentity(owner);
165	        // Joining an existing household is now permitted (an exact-identity duplicate is still
166	        // rejected above); a joiner's membershipLevel is instead capped one above the household's
167	        // current maximum (see cappedMembershipLevel).
168	        String region = Localities.region(owner.getPostcode(), owner.getCity());
169	        owner.setCustomerCode(assignCustomerCode(region, owner.getTelephone(), owner.getLastName()));
170	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
171	        owner.setBulkSignupWarning(computeBulkSignupWarning(registrationDate));
172	        owner.setHouseholdSize(countHouseholdMembers(owner.getLastName(), owner.getPostcode()) + 1);
173	        owner.setMembershipLevel(cappedMembershipLevel(owner));
174	        // A declared household member (sharesHousehold) is created but is not a suspected duplicate.
175	        Integer possibleDuplicateOf = sharesHousehold ? null : findPossibleDuplicateOf(owner);
176	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
177	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
178	        this.clinicService.saveOwner(owner);
179	        if (idempotencyKey != null) {
180	            idempotencyKeyToOwnerId.put(idempotencyKey, owner.getId());
181	        }
182	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
183	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
184	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
185	            ownerDto.getMembershipLevel(), ownerDto.getMembershipNumber());
186	        headers.setLocation(UriComponentsBuilder.newInstance()
187	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
188	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
189	    }
190	
191	    /**
192	     * Reads the optional {@code Idempotency-Key} header from the current request, if any. A create
193	     * carrying this header is idempotent: the first create under a key is recorded, and a later create
194	     * with the same key returns the originally created owner instead of creating a duplicate.
195	     *
196	     * @return the trimmed idempotency key, or {@code null} when the header is absent, blank or there is
197	     *         no active servlet request
198	     */
199	    private String currentIdempotencyKey() {
200	        RequestAttributes attributes = RequestContextHolder.getRequestAttributes();
201	        if (attributes instanceof ServletRequestAttributes servletAttributes) {
202	            String key = servletAttributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
203	            if (key != null && !key.isBlank()) {
204	                return key.trim();
205	            }
206	        }
207	        return null;
208	    }
209	
210	    /**
211	     * Rejects creating an owner whose supplied {@code registrationDate} is later than the server
212	     * date (in the future). Only an explicitly supplied date is validated; a {@code null} date
213	     * (which later defaults to the server date) is accepted. The check is against the raw supplied
214	     * date, before any business-day adjustment.
215	     *
216	     * @param registrationDate the supplied registration date, or {@code null} when none was supplied
217	     * @throws FutureRegistrationDateException (400 Bad Request) if the supplied date is in the future
218	     */
219	    private void rejectFutureRegistrationDate(java.time.LocalDate registrationDate) {
220	        if (registrationDate != null && registrationDate.isAfter(java.time.LocalDate.now())) {
221	            throw new FutureRegistrationDateException(registrationDate);
222	        }
223	    }
224	
225	    /**
226	     * The maximum number of owners that may be created in a single day. Creating an owner once this
227	     * many owners already carry today's {@code registrationDate} is rejected.
228	     */
229	    private static final int DAILY_OWNER_LIMIT = 100;
230	
231	    /**
232	     * Rejects creating an owner once {@value #DAILY_OWNER_LIMIT} or more owners already carry the
233	     * given business day as their {@code registrationDate}. The count is keyed by the
234	     * business-day-adjusted registration date of the owner being created (see
235	     * {@link #toBusinessDay}), so all owners falling on the same business day count together. Owners
236	     * with no {@code registrationDate} are ignored.
237	     *
238	     * @param registrationDate the business-day-adjusted registration date of the owner being created
239	     * @throws DailyOwnerLimitException (429 Too Many Requests) if the daily limit is already reached
240	     */
241	    private void rejectDailyLimitReached(java.time.LocalDate registrationDate) {
242	        long count = this.clinicService.findAllOwners().stream()
243	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
244	            .count();
245	        if (count >= DAILY_OWNER_LIMIT) {
246	            throw new DailyOwnerLimitException(registrationDate);
247	        }
248	    }
249	
250	    /**
251	     * The threshold of owners already created on a business day beyond which a bulk-signup warning is
252	     * raised on a new owner. Once strictly more than this many owners already carry the day as their
253	     * {@code registrationDate}, the new owner's {@code bulkSignupWarning} is set to {@code true}.
254	     */
255	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
256	
257	    /**
258	     * Computes the {@code bulkSignupWarning} for an owner being created: {@code true} when more than
259	     * {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been created today, otherwise
260	     * {@code false}. Existing owners are counted the same way the daily-limit rule counts them (see
261	     * {@link #rejectDailyLimitReached}), keyed by the business-day-adjusted registration date, and the
262	     * owner being created is excluded (it has not yet been saved).
263	     *
264	     * @param registrationDate the business-day-adjusted registration date of the owner being created
265	     * @return {@code true} if more than the threshold of owners already carry this business day
266	     */
267	    private boolean computeBulkSignupWarning(java.time.LocalDate registrationDate) {
268	        long count = this.clinicService.findAllOwners().stream()
269	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
270	            .count();
271	        return count > BULK_SIGNUP_WARNING_THRESHOLD;
272	    }
273	
274	    /**
275	     * The fixed public holidays the business-day roll skips. A registration date landing on any of
276	     * these dates is rolled forward, just as it is for a weekend.
277	     */
278	    private static final java.util.Set<java.time.LocalDate> PUBLIC_HOLIDAYS = java.util.Set.of(
279	        java.time.LocalDate.parse("2026-01-01"),
280	        java.time.LocalDate.parse("2026-01-26"),
281	        java.time.LocalDate.parse("2026-04-25"),
282	        java.time.LocalDate.parse("2026-12-25"),
283	        java.time.LocalDate.parse("2026-12-28"));
284	
285	    /**
286	     * Rolls a registration date forward onto a business day: a Saturday, Sunday or listed public
287	     * holiday is moved forward to the next non-holiday weekday; an ordinary weekday is returned
288	     * unchanged. This applies to the effective registration date whether it was supplied in the
289	     * request or defaulted to the server date, and every value derived from the registration date
290	     * uses the adjusted result.
291	     *
292	     * @param date the effective registration date
293	     * @return {@code date} itself when it is a non-holiday weekday, otherwise the next business day
294	     */
295	    private java.time.LocalDate toBusinessDay(java.time.LocalDate date) {
296	        while (date.getDayOfWeek() == java.time.DayOfWeek.SATURDAY
297	            || date.getDayOfWeek() == java.time.DayOfWeek.SUNDAY
298	            || PUBLIC_HOLIDAYS.contains(date)) {
299	            date = date.plusDays(1);
300	        }
301	        return date;
302	    }
303	
304	    /**
305	     * The maximum number of owners a single city may contain. Creating an owner in a city that
306	     * already holds this many owners is rejected.
307	     */
308	    private static final int CITY_CAPACITY = 50;
309	
310	    /**
311	     * Rejects creating an owner whose city already contains {@value #CITY_CAPACITY} or more owners.
312	     * Owners are counted per city comparing the city name case-insensitively (a {@code null} city is
313	     * treated as empty).
314	     *
315	     * @param city the city of the owner being created
316	     * @throws CityAtCapacityException (409 Conflict) if the city is already at capacity
317	     */
318	    private void rejectCityAtCapacity(String city) {
319	        String cityValue = city == null ? "" : city;
320	        long count = this.clinicService.findAllOwners().stream()
321	            .filter(existing -> cityValue.equalsIgnoreCase(
322	                existing.getCity() == null ? "" : existing.getCity()))
323	            .count();
324	        if (count >= CITY_CAPACITY) {
325	            throw new CityAtCapacityException(city);
326	        }
327	    }
328	
329	    /**
330	     * Assigns an owner's {@code customerCode} on create, formatted {@code '<REGION>-<HASH8>'} where
331	     * REGION is the owner's canonical region (derived by preferring the postcode, see
332	     * {@link Localities#region(String, String)} — the same region derivation shared with the
333	     * {@code locality}) and HASH8 is the first 8 upper-case hex characters of the SHA-256 digest of
334	     * the normalized (E.164) telephone concatenated with the last name (e.g. {@code 'NSW-3A7F9C2E'}).
335	     * The code is derived from the owner's own identity fields; it carries no sequence number.
336	     * <p>
337	     * When the computed code collides with an existing owner's {@code customerCode}, it is
338	     * de-duplicated by appending {@code '-<n>'} with the smallest {@code n} of 2 or more that makes
339	     * it unique (e.g. {@code 'NSW-3A7F9C2E-2'}), and the de-duplicated code is returned.
340	     *
341	     * @param region the owner's canonical region (the identity's REGION, shared with the locality)
342	     * @param telephone the owner's normalized (E.164) telephone
343	     * @param lastName the owner's last name
344	     * @return the assigned customer code, de-duplicated to be unique among existing owners
345	     */
346	    private String assignCustomerCode(String region, String telephone, String lastName) {
347	        String basis = (telephone == null ? "" : telephone) + (lastName == null ? "" : lastName);
348	        String hash8 = sha256UpperHex(basis).substring(0, 8);
349	        String code = region + "-" + hash8;
350	        java.util.Set<String> existing = this.clinicService.findAllOwners().stream()
351	            .map(Owner::getCustomerCode)
352	            .filter(java.util.Objects::nonNull)
353	            .collect(java.util.stream.Collectors.toSet());
354	        if (!existing.contains(code)) {
355	            return code;
356	        }
357	        for (int n = 2; ; n++) {
358	            String candidate = code + "-" + n;
359	            if (!existing.contains(candidate)) {
360	                return candidate;
361	            }
362	        }
363	    }
364	
365	    /**
366	     * Returns the full upper-case hex SHA-256 digest of the UTF-8 bytes of {@code value}.
367	     */
368	    private static String sha256UpperHex(String value) {
369	        try {
370	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
371	                .digest(value.getBytes(java.nio.charset.StandardCharsets.UTF_8));
372	            StringBuilder sb = new StringBuilder(digest.length * 2);
373	            for (byte b : digest) {
374	                sb.append(String.format("%02X", b));
375	            }
376	            return sb.toString();
377	        }
378	        catch (java.security.NoSuchAlgorithmException e) {
379	            throw new IllegalStateException("SHA-256 not available", e);
380	        }
381	    }
382	
383	    /**
384	     * Counts how many existing owners share the given first and last name, compared
385	     * case-insensitively, at the time this owner is created. The value excludes the owner
386	     * being created (which has not yet been saved) and is stored on the new owner and returned
387	     * as its {@code namesakeCount}.
388	     *
389	     * @param firstName the first name of the owner being created
390	     * @param lastName the last name of the owner being created
391	     * @return the number of existing owners with the same first and last name
392	     */
393	    private int countNamesakes(String firstName, String lastName) {
394	        String first = firstName == null ? "" : firstName;
395	        String last = lastName == null ? "" : lastName;
396	        return (int) this.clinicService.findAllOwners().stream()
397	            .filter(existing -> first.equalsIgnoreCase(existing.getFirstName())
398	                && last.equalsIgnoreCase(existing.getLastName()))
399	            .count();
400	    }
401	
402	    /**
403	     * Counts how many existing owners belong to the same household as the owner being created, i.e.
404	     * share its {@code householdId} (derived by {@link Households#householdId} from the normalized last
405	     * name and postcode). The value excludes the owner being created (which has not yet been saved), so
406	     * the household's size after this create is this count plus one. It is stored on the new owner.
407	     *
408	     * @param lastName the last name of the owner being created
409	     * @param postcode the postcode of the owner being created
410	     * @return the number of existing owners sharing this owner's household
411	     */
412	    private int countHouseholdMembers(String lastName, String postcode) {
413	        String householdId = Households.householdId(lastName, postcode);
414	        return (int) this.clinicService.findAllOwners().stream()
415	            .filter(existing -> householdId.equals(
416	                Households.householdId(existing.getLastName(), existing.getPostcode())))
417	            .count();
418	    }
419	
420	    /**
421	     * Computes the {@code membershipLevel} to store for the owner being created, applying the household
422	     * ceiling. The owner's natural level is first derived from their own fields (see
423	     * {@link org.springframework.samples.petclinic.util.Memberships#membershipLevel(String, Integer, Integer, java.time.LocalDate)}).
424	     * It is then capped so it cannot exceed one above the current maximum {@code membershipLevel} among
425	     * the owner's existing household members (the non-deleted owners sharing its {@code householdId}, see
426	     * {@link Households#householdId}). When the owner has no existing household member no cap applies and
427	     * the natural level is returned.
428	     *
429	     * @param owner the owner being created, with its level-affecting fields already populated
430	     * @return the (possibly capped) membership level to store on the owner
431	     */
432	    private int cappedMembershipLevel(Owner owner) {
433	        int naturalLevel = org.springframework.samples.petclinic.util.Memberships.membershipLevel(
434	            owner.getEmail(), owner.getNamesakeCount(), owner.getHouseholdSize(), owner.getRegistrationDate());
435	        String householdId = Households.householdId(owner.getLastName(), owner.getPostcode());
436	        java.util.OptionalInt maxMemberLevel = this.clinicService.findAllOwners().stream()
437	            .filter(this::isNotDeleted)
438	            .filter(existing -> householdId.equals(
439	                Households.householdId(existing.getLastName(), existing.getPostcode())))
440	            .mapToInt(this::effectiveMembershipLevel)
441	            .max();
442	        if (maxMemberLevel.isEmpty()) {
443	            return naturalLevel;
444	        }
445	        return Math.min(naturalLevel, maxMemberLevel.getAsInt() + 1);
446	    }
447	
448	    /**
449	     * Returns an existing owner's effective {@code membershipLevel}: the stored value when present (the
450	     * value assigned, and possibly capped, when that owner was created), otherwise the level derived
451	     * from its own fields for owners that predate the stored level (e.g. seed data).
452	     *
453	     * @param owner an existing owner
454	     * @return the owner's effective membership level
455	     */
456	    private int effectiveMembershipLevel(Owner owner) {
457	        if (owner.getMembershipLevel() != null) {
458	            return owner.getMembershipLevel();
459	        }
460	        return org.springframework.samples.petclinic.util.Memberships.membershipLevel(
461	            owner.getEmail(), owner.getNamesakeCount(), owner.getHouseholdSize(), owner.getRegistrationDate());
462	    }
463	
464	    /**
465	     * Finds the existing owner, if any, that the owner being created is a soft duplicate of: an owner
466	     * sharing this owner's {@code soundex(lastName)} and postcode (an exact match of the stored 4-digit
467	     * value) while carrying a <em>different</em> {@code identityKey}. A soft match is distinct from the
468	     * hard duplicate rejected earlier by {@link #rejectDuplicateIdentity} (which requires an identical
469	     * identity key): the owner is still created, but flagged. Because the telephone is part of the
470	     * identity key, two owners with the same last name and postcode but different telephones are a soft
471	     * match rather than a hard duplicate. When more than one existing owner matches, the earliest
472	     * (lowest id) is returned so the reference is deterministic. An owner with no postcode can never
473	     * soft-match.
474	     *
475	     * @param owner the owner being created, with its telephone and postcode already normalized/validated
476	     * @return the id of the matching existing owner, or {@code null} when there is no soft match
477	     */
478	    private Integer findPossibleDuplicateOf(Owner owner) {
479	        String postcode = owner.getPostcode();
480	        if (postcode == null) {
481	            return null;
482	        }
483	        String soundex = Households.soundex(owner.getLastName());
484	        String identity = Households.identityKey(owner.getTelephone(), owner.getEmail(), owner.getLastName());
485	        return this.clinicService.findAllOwners().stream()
486	            .filter(this::isNotDeleted)
487	            .filter(existing -> soundex.equals(Households.soundex(existing.getLastName())))
488	            .filter(existing -> postcode.equals(existing.getPostcode()))
489	            .filter(existing -> !identity.equals(Households.identityKey(
490	                toE164OrNull(existing.getTelephone()), existing.getEmail(), existing.getLastName())))
491	            .map(Owner::getId)
492	            .filter(java.util.Objects::nonNull)
493	            .min(java.util.Comparator.naturalOrder())
494	            .orElse(null);
495	    }
496	
497	    /**
498	     * Normalizes an owner's telephone on create into E.164 form. Spaces, dashes and brackets are
499	     * stripped. A leading '+' and its country code are kept as given; otherwise country code '+61' is
500	     * assumed and a single leading '0' is dropped from the national digits. The resulting number must
501	     * have 8 to 15 digits after the '+'. For example {@code "0412 345 678"} becomes
502	     * {@code "+61412345678"}. The E.164 value is stored and returned.
503	     * <p>
504	     * The national-number length (the digits after the country code) is additionally validated for
505	     * country codes with a fixed length: '+61' requires exactly 9 national digits and '+1' requires
506	     * exactly 10. Numbers of other country codes are only bound by the overall 8-to-15-digit limit.
507	     *
508	     * @param telephone the raw telephone as submitted
509	     * @return the normalized E.164 telephone (a '+' followed by 8 to 15 digits)
510	     * @throws InvalidTelephoneException (400 Bad Request) if the value cannot form a valid E.164 number
511	     *         or its national-number length is wrong for its country code
512	     */
513	    private String normalizeTelephone(String telephone) {
514	        String raw = telephone == null ? "" : telephone.trim();
515	        boolean hasCountryCode = raw.startsWith("+");
516	        String cleaned = raw.replaceAll("[\\s()\\-]", "");
517	        if (hasCountryCode) {
518	            cleaned = cleaned.substring(1);
519	        }
520	        String digits;
521	        if (hasCountryCode) {
522	            digits = cleaned;
523	        } else {
524	            if (cleaned.startsWith("0")) {
525	                cleaned = cleaned.substring(1);
526	            }
527	            digits = "61" + cleaned;
528	        }
529	        if (!digits.matches("[0-9]{8,15}") || !hasValidNationalLength(digits)) {
530	            throw new InvalidTelephoneException(telephone);
531	        }
532	        return "+" + digits;
533	    }
534	
535	    /**
536	     * Checks the national-number length of an E.164 digit string against its country code for the
537	     * country codes whose national number has a fixed length: '+61' requires 9 national digits and
538	     * '+1' requires 10. Any other country code passes, leaving it bound only by the overall length.
539	     *
540	     * @param digits the E.164 digits (the country code followed by the national number, without '+')
541	     * @return {@code true} if the national-number length is acceptable for the country code
542	     */
543	    private boolean hasValidNationalLength(String digits) {
544	        if (digits.startsWith("61")) {
545	            return digits.length() - 2 == 9;
546	        }
547	        if (digits.startsWith("1")) {
548	            return digits.length() - 1 == 10;
549	        }
550	        return true;
551	    }
552	
553	    /**
554	     * Syntactic email pattern: a non-empty local part, an '@', a domain with at least one dot and a
555	     * multi-character top-level label. Deliberately lenient about the exact character set while still
556	     * rejecting values that are clearly not addresses (e.g. missing '@').
557	     */
558	    private static final java.util.regex.Pattern EMAIL_PATTERN =
559	        java.util.regex.Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]{2,}$");
560	
561	    /**
562	     * Domains of known disposable/throwaway email providers. An owner whose email domain is on this
563	     * blocklist is rejected with a 400 Bad Request. Compared case-insensitively against the
564	     * lower-cased email domain.
565	     */
566	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS = java.util.Set.of(
567	        "mailinator.com", "tempmail.com", "guerrillamail.com");
568	
569	    /**
570	     * Normalizes an owner's email. Email is optional: a {@code null} or blank value is left as
571	     * {@code null} (no email). When present it must be a syntactically valid address; the value is
572	     * lower-cased before being stored and returned.
573	     *
574	     * @param email the raw email as submitted, may be {@code null}
575	     * @return the lower-cased email, or {@code null} when none was supplied
576	     * @throws InvalidEmailException (400 Bad Request) if a non-blank value is not a valid address
577	     */
578	    private String normalizeEmail(String email) {
579	        if (email == null || email.isBlank()) {
580	            return null;
581	        }
582	        String trimmed = email.trim();
583	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
584	            throw new InvalidEmailException(email);
585	        }
586	        String normalized = trimmed.toLowerCase(java.util.Locale.ROOT);
587	        String domain = normalized.substring(normalized.indexOf('@') + 1);
588	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
589	            throw new DisposableEmailException(email);
590	        }
591	        return normalized;
592	    }
593	
594	    /**
595	     * Fixed region-to-postcode-range table: a region's postcode must fall within its inclusive range
596	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city whose region is not listed here (see
597	     * {@link Localities#region}) accepts any 4-digit postcode.
598	     */
599	    private static final java.util.Map<String, int[]> REGION_POSTCODE_RANGES = java.util.Map.of(
600	        "NSW", new int[] {2000, 2099},
601	        "VIC", new int[] {3000, 3099},
602	        "QLD", new int[] {4000, 4099});
603	
604	    /**
605	     * Validates an owner's postcode on create. The postcode is optional: a {@code null} or blank value
606	     * is left as {@code null} (no postcode) and accepted. When present it must be exactly 4 digits and,
607	     * for a city whose region is in the fixed {@link #REGION_POSTCODE_RANGES range table}, must fall
608	     * within that region's inclusive range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no
609	     * known region accepts any 4-digit postcode. The value is stored and returned exactly as supplied.
610	     *
611	     * @param city the owner's city, used to derive the region whose range constrains the postcode
612	     * @param postcode the raw postcode as submitted, may be {@code null}
613	     * @return the postcode when supplied, or {@code null} when none was supplied
614	     * @throws InvalidPostcodeException (400 Bad Request) if a supplied postcode is not 4 digits or is
615	     *         out of range for the city's region
616	     */
617	    private String validatePostcode(String city, String postcode) {
618	        if (postcode == null || postcode.isBlank()) {
619	            return null;
620	        }
621	        if (!postcode.matches("[0-9]{4}")) {
622	            throw new InvalidPostcodeException(postcode);
623	        }
624	        int[] range = REGION_POSTCODE_RANGES.get(Localities.region(city));
625	        if (range != null) {
626	            int value = Integer.parseInt(postcode);
627	            if (value < range[0] || value > range[1]) {
628	                throw new InvalidPostcodeException(postcode);
629	            }
630	        }
631	        return postcode;
632	    }
633	
634	    /**
635	     * Common street-type abbreviations expanded to their full word during address normalization.
636	     */
637	    private static final java.util.Map<String, String> ADDRESS_ABBREVIATIONS = java.util.Map.of(
638	        "ST", "STREET",
639	        "RD", "ROAD",
640	        "AVE", "AVENUE");
641	
642	    /**
643	     * Applies the owner's address on create from the structured fields when present, falling back to the
644	     * flat {@code address} for backward compatibility. An owner must supply an address in at least one
645	     * form: a non-blank {@code addressLine1} (the structured form, preferred) or a non-blank flat
646	     * {@code address}; when neither is present the create is rejected.
647	     * <p>
648	     * Whichever address fields are supplied are normalized (see {@link #normalizeAddress}). When the
649	     * structured form is used the normalized {@code addressLine1} and, when supplied, {@code addressLine2}
650	     * are stored on the owner and the composed {@code address} is the normalized {@code addressLine1} with
651	     * a single space and the normalized {@code addressLine2} appended when {@code addressLine2} is present.
652	     * When only the flat form is used the normalized flat value becomes the stored {@code address} and the
653	     * structured lines are left unset. The stored {@code address} is the value every later step reads.
654	     *
655	     * @param owner the owner being created
656	     * @param ownerFieldsDto the submitted owner fields carrying the raw address input
657	     * @throws InvalidAddressException (400 Bad Request) if no address is supplied in either form
658	     */
659	    private void applyAddress(Owner owner, OwnerFieldsDto ownerFieldsDto) {
660	        String rawLine1 = ownerFieldsDto.getAddressLine1();
661	        String rawLine2 = ownerFieldsDto.getAddressLine2();
662	        String rawFlat = ownerFieldsDto.getAddress();
663	        boolean hasLine1 = rawLine1 != null && !rawLine1.isBlank();
664	        boolean hasFlat = rawFlat != null && !rawFlat.isBlank();
665	        if (!hasLine1 && !hasFlat) {
666	            throw new InvalidAddressException(rawLine1 != null ? rawLine1 : rawFlat);
667	        }
668	        if (hasLine1) {
669	            String line1 = normalizeAddress(rawLine1);
670	            String line2 = (rawLine2 != null && !rawLine2.isBlank()) ? normalizeAddress(rawLine2) : null;
671	            owner.setAddressLine1(line1);
672	            owner.setAddressLine2(line2);
673	            owner.setAddress(line2 != null ? line1 + " " + line2 : line1);
674	        } else {
675	            owner.setAddressLine1(null);
676	            owner.setAddressLine2(null);
677	            owner.setAddress(normalizeAddress(rawFlat));
678	        }
679	    }
680	
681	    /**
682	     * Normalizes an owner's address on create. Surrounding whitespace is trimmed and internal runs of
683	     * whitespace collapse to a single space, the value is upper-cased and common street-type
684	     * abbreviations are expanded to their full word ({@code ST} to {@code STREET}, {@code RD} to
685	     * {@code ROAD}, {@code AVE} to {@code AVENUE}). For example {@code "  12  main  st "} becomes
686	     * {@code "12 MAIN STREET"}. The normalized value is stored and returned, and is also the form used
687	     * for every address comparison (household duplicate detection and the shared household id).
688	     *
689	     * @param address the raw address as submitted
690	     * @return the normalized address
691	     * @throws InvalidAddressException (400 Bad Request) if the address is blank after normalization
692	     */
693	    private String normalizeAddress(String address) {
694	        String collapsed = (address == null ? "" : address).trim().replaceAll("\\s+", " ");
695	        if (collapsed.isEmpty()) {
696	            throw new InvalidAddressException(address);
697	        }
698	        String[] tokens = collapsed.toUpperCase(java.util.Locale.ROOT).split(" ");
699	        StringBuilder normalized = new StringBuilder(collapsed.length());
700	        for (int i = 0; i < tokens.length; i++) {
701	            if (i > 0) {
702	                normalized.append(' ');
703	            }
704	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
705	        }
706	        return normalized.toString();
707	    }
708	
709	    /**
710	     * Rejects creating an owner whose identity duplicates an existing owner's. All duplicate detection
711	     * is consolidated onto the single derived {@code identityKey} (see
712	     * {@link Households#identityKey(String, String, String)}): the SHA-256 hex over the normalized
713	     * telephone, the lower-cased email (a {@code null} email compared as an empty segment) and the
714	     * {@code soundex} of the last name. Two owners are duplicates when their identity keys are equal.
715	     * Existing telephones are re-normalized to E.164 before comparison, so equivalent values submitted
716	     * in different formats (e.g. national {@code "0412 345 678"} and international
717	     * {@code "+61 412 345 678"}) still match. The email-domain blocklist is applied first (during
718	     * email normalization), and soft-deleted owners are ignored.
719	     * <p>
720	     * Because the telephone is part of the key, two members of one household (same last name and
721	     * postcode) with different telephones have different identity keys and are both allowed; such a
722	     * near-match is instead surfaced as a soft duplicate (see {@link #findPossibleDuplicateOf}).
723	     *
724	     * @param owner the owner being created, with its telephone and email already normalized
725	     * @throws DuplicateIdentityException (409 Conflict) if another owner has the same identity key
726	     */
727	    private void rejectDuplicateIdentity(Owner owner) {
728	        String identity = Households.identityKey(owner.getTelephone(), owner.getEmail(), owner.getLastName());
729	        boolean duplicate = this.clinicService.findAllOwners().stream()
730	            .filter(this::isNotDeleted)
731	            .anyMatch(existing -> identity.equals(Households.identityKey(
732	                toE164OrNull(existing.getTelephone()), existing.getEmail(), existing.getLastName())));
733	        if (duplicate) {
734	            throw new DuplicateIdentityException(identity);
735	        }
736	    }
737	
738	    /**
739	     * Whether an existing owner is not soft-deleted. A soft-deleted owner (its {@code deleted} flag
740	     * set) is retained but ignored by the create endpoint's duplicate and identity checks, so a
741	     * normally-blocking duplicate is allowed when the only matching owner has been deleted.
742	     */
743	    private boolean isNotDeleted(Owner owner) {
744	        return !Boolean.TRUE.equals(owner.getDeleted());
745	    }
746	
747	    /**
748	     * Normalizes an existing owner's telephone to E.164 for duplicate comparison, returning
749	     * {@code null} instead of throwing when the stored value cannot form a valid E.164 number, or
750	     * when its national-number length does not match its country code.
751	     */
752	    private String toE164OrNull(String telephone) {
753	        try {
754	            return normalizeTelephone(telephone);
755	        } catch (InvalidTelephoneException e) {
756	            return null;
757	        }
758	    }
759	
760	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
761	    @Override
762	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
763	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
764	        if (currentOwner == null) {
765	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
766	        }
767	        currentOwner.setAddress(ownerFieldsDto.getAddress());
768	        currentOwner.setCity(ownerFieldsDto.getCity());
769	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
770	        currentOwner.setLastName(ownerFieldsDto.getLastName());
771	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
772	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
773	        this.clinicService.saveOwner(currentOwner);
774	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
775	    }
776	
777	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
778	    @Transactional
779	    @Override
780	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
781	        Owner owner = this.clinicService.findOwnerById(ownerId);
782	        if (owner == null) {
783	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
784	        }
785	        this.clinicService.deleteOwner(owner);
786	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
787	    }
788	
789	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
790	    @Override
791	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
792	        Owner owner = this.clinicService.findOwnerById(ownerId);
793	        if (owner == null) {
794	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
795	        }
796	        HttpHeaders headers = new HttpHeaders();
797	        Pet pet = petMapper.toPet(petFieldsDto);
798	        owner.setId(ownerId);
799	        pet.setOwner(owner);
800	        pet.getType().setName(null);
801	        this.clinicService.savePet(pet);
802	        PetDto petDto = petMapper.toPetDto(pet);
803	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
804	            .buildAndExpand(pet.getId()).toUri());
805	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
806	    }
807	
808	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
809	    @Override
810	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
811	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
812	        if (currentOwner != null) {
813	            Pet currentPet = this.clinicService.findPetById(petId);
814	            if (currentPet != null) {
815	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
816	                currentPet.setName(petFieldsDto.getName());
817	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
818	                this.clinicService.savePet(currentPet);
819	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
820	            }
821	        }
822	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
823	    }
824	
825	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
826	    @Override
827	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
828	        HttpHeaders headers = new HttpHeaders();
829	        Visit visit = visitMapper.toVisit(visitFieldsDto);
830	        Pet pet = new Pet();
831	        pet.setId(petId);
832	        visit.setPet(pet);
833	        this.clinicService.saveVisit(visit);
834	        VisitDto visitDto = visitMapper.toVisitDto(visit);
835	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
836	            .buildAndExpand(visit.getId()).toUri());
837	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
838	    }
839	
840	
841	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
842	    @Override
843	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
844	        Owner owner = this.clinicService.findOwnerById(ownerId);
845	        if (owner != null) {
846	            Pet pet = owner.getPet(petId);
847	            if (pet != null) {
848	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
849	            }
850	        }
851	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
852	    }
853	}
